contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address token, address to1, address to2, uint v, bool emptyList) public returns (bool) {
        address[] memory tos = new address[](emptyList ? 0 : 2);
        if (!emptyList) {
            tos[0] = to1;
            tos[1] = to2;
        }
        if (emptyList) {
            bool reverted;
            try c.transfer(from, token, tos, v) { reverted = false; } catch { reverted = true; }
            assert(reverted);
            return false;
        } else {
            bool ok = c.transfer(from, token, tos, v);
            assert(ok);
            return true;
        }
    }
    receive() external payable {}
}

